    [pbr::OriginalName("WARM_INTRO_TEXT_SOURCE_TEMPLATE")] Template = 1,
    /// <summary>
    /// &lt;i>Phase B&lt;/i>: an LLM summary of the call so far, instructed by &lt;code>WarmTransferConfig.intro_prompt&lt;/code>;
